func eventStartDate(ctx context.Context, e *bongov1.Event, date string) string {
	if e != nil && e.StartTime > 0 {
		if e.AllDay {
			return icalevent.AllDayDate(e.StartTime).Format("2006-01-02")
		}
		return time.Unix(e.StartTime, 0).In(calendarNow(ctx).Location()).Format("2006-01-02")
	}
	if date != "" {
		return date
	}
	return calendarNow(ctx).Format("2006-01-02")
}

func eventStartTime(ctx context.Context, e *bongov1.Event) string {
	if e != nil && e.StartTime > 0 && !e.AllDay {
		return time.Unix(e.StartTime, 0).In(calendarNow(ctx).Location()).Format("15:04")
	}
	return "09:00"
}

func eventEndDate(ctx context.Context, e *bongov1.Event, date string) string {
	if e != nil && e.EndTime > 0 {
		t := time.Unix(e.EndTime, 0).In(calendarNow(ctx).Location())
		if e.AllDay {
			t = icalevent.AllDayDate(e.EndTime).AddDate(0, 0, -1)
		}
		return t.Format("2006-01-02")
	}
	if date != "" {
		return date
	}
	return calendarNow(ctx).Format("2006-01-02")
}

func eventEndTime(ctx context.Context, e *bongov1.Event) string {
	if e != nil && e.EndTime > 0 && !e.AllDay {
		return time.Unix(e.EndTime, 0).In(calendarNow(ctx).Location()).Format("15:04")
	}
	return "10:00"
}

// eventFormData is the x-data of the event form: the registered eventForm
// component, with the all-day state and the scope choice. A form opened from
// an occurrence starts on "this event", the least destructive choice.
func eventFormData(ctx context.Context, e *bongov1.Event, isNew bool, date string) string {
	allDay := "false"
	if e != nil && e.AllDay {
		allDay = "true"
	}
	// A saved event keeps its stored choice when the checkbox changes; a new
	// one follows the checkbox until the user picks.
	touched := "false"
	if !isNew {
		touched = "true"
	}
	scope := "all"
	if occurrenceFromCtx(ctx) != nil && !isNew {
		scope = "this"
	}
	return fmt.Sprintf("eventForm(%s, '%s', '%s', %s)", allDay, scope, eventShowAs(e, isNew), touched)
}

// eventShowAs is the Show as choice the form starts on: the stored one for a
// saved event, Free for a new all-day event and Busy for a new timed one.
func eventShowAs(e *bongov1.Event, isNew bool) string {
	free := e != nil && e.Transparent
	if isNew {
		free = e != nil && e.AllDay
	}
	if free {
		return "free"
	}
	return "busy"
}

func prevWeekYear(year, week int) int {
	if week <= 1 {
		return year - 1
	}
	return year
}

func prevWeekNum(year, week int) int {
	if week <= 1 {
		return 52
	}
	return week - 1
}

func nextWeekYear(year, week int) int {
	if week >= 52 {
		return year + 1
	}
	return year
}

func nextWeekNum(year, week int) int {
	if week >= 52 {
		return 1
	}
	return week + 1
}

